namespace ws::cfg {

template<typename From, typename To>
struct VarConverter {
    To operator()(const From& val) const noexcept {
        return static_cast<To>(val);
    }
};

// Specializations for string conversions

template<typename To>
struct VarConverter<std::string, To> {
    To operator()(const std::string& val) const {
        To result;
        std::istringstream iss(val);
        iss >> result;
        if (iss.fail()) {
            throw std::runtime_error("Conversion failed");
        }
        return result;
    }
};

// Specialization for string to string

template<>
struct VarConverter<std::string, std::string> {
    std::string operator()(const std::string& val) const noexcept {
        return val;
    }
};

// Specializations for container types

template<typename T>
struct VarConverter<std::string, std::list<T>> {
    std::list<T> operator()(const std::string& val) const {
        YAML::Node node = YAML::Load(val);
        if (!node.IsSequence()) {
            throw std::runtime_error("Expected sequence");
        }
        return node.as<std::list<T>>();
    }
};

// ... (other specializations for vector, set, unordered_set, map, unordered_map)

class VarBase {
public:
    using Ptr = std::shared_ptr<VarBase>;

    VarBase(std::string_view name, std::string_view description = "") noexcept;
    virtual ~VarBase() noexcept = default;

    std::string_view Name() const noexcept;
    std::string_view Description() const noexcept;

    virtual std::string ToString() const noexcept = 0;
    virtual void FromString(std::string_view str) = 0;

private:
    std::string name_;
    std::string description_;
};

template<typename T, typename FromStr = VarConverter<std::string, T>, typename ToStr = VarConverter<T, std::string>>
class Var : public VarBase {
public:
    using Ptr = std::shared_ptr<Var>;

    Var(std::string_view name, const T& default_val, std::string_view description = "") noexcept;

    std::string ToString() const noexcept override;
    void FromString(std::string_view str) override;

    T GetValue() const noexcept;
    void SetValue(const T& val) noexcept;

    std::string_view TypeName() const noexcept;

    void RemoveListener(std::uint64_t key) noexcept;
    std::uint64_t AddListener(std::function<void(const T&)> listener) noexcept;
    void ClearListeners() noexcept;

private:
    mutable std::shared_mutex mtx_;
    T val_;
    std::unordered_map<std::uint64_t, std::function<void(const T&)>> listeners_;
};

class Config {
public:
    using Ptr = std::shared_ptr<Config>;

    Config(std::string_view name) noexcept;

    std::string_view Name() const noexcept;

    template<typename T>
    typename Var<T>::Ptr Lookup(std::string_view name, const T& default_val, std::string_view description = "") {
        std::lock_guard lock(mtx_);
        auto it = vars_.find(std::string(name));
        if (it == vars_.end()) {
            auto var = std::make_shared<Var<T>>(name, default_val, description);
            vars_[std::string(name)] = var;
            return var;
        }
        return std::static_pointer_cast<Var<T>>(it->second);
    }

    template<typename T>
    typename Var<T>::Ptr Lookup(std::string_view name) const {
        std::lock_guard lock(mtx_);
        auto it = vars_.find(std::string(name));
        if (it == vars_.end()) {
            throw std::runtime_error("Variable not found");
        }
        return std::static_pointer_cast<Var<T>>(it->second);
    }

    VarBase::Ptr LookupBase(std::string_view name) const noexcept;

    void LoadYaml(const YAML::Node& root);

    void Visit(std::function<void(VarBase::Ptr)> visitor) const noexcept;

private:
    mutable std::shared_mutex mtx_;
    std::string name_;
    std::unordered_map<std::string, VarBase::Ptr> vars_;
};

Config::Ptr RootConfig() noexcept;
}

#include "config.h"
#include <yaml-cpp/yaml.h>

namespace ws::cfg {

VarBase::VarBase(std::string_view name, std::string_view description) noexcept : name_(name), description_(description) {}

std::string_view VarBase::Name() const noexcept {
    return name_;
}

std::string_view VarBase::Description() const noexcept {
    return description_;
}

Config::Config(std::string_view name) noexcept : name_(name) {}

std::string_view Config::Name() const noexcept {
    return name_;
}

VarBase::Ptr Config::LookupBase(std::string_view name) const noexcept {
    std::lock_guard lock(mtx_);
    auto it = vars_.find(std::string(name));
    if (it == vars_.end()) {
        return nullptr;
    }
    return it->second;
}

void Config::LoadYaml(const YAML::Node& root) {
    auto members = ExtractMembers(root);
    for (const auto& [key, node] : members) {
        if (!key.empty()) {
            auto var = LookupBase(key);
            if (var) {
                try {
                    var->FromString(node.Scalar());
                } catch (...) {
                    // Exception handling as per design spec
                }
            }
        }
    }
}

void Config::Visit(std::function<void(VarBase::Ptr)> visitor) const noexcept {
    std::lock_guard lock(mtx_);
    for (const auto& [name, var] : vars_) {
        visitor(var);
    }
}

Config::Ptr RootConfig() noexcept {
    static Config::Ptr instance = std::make_shared<Config>("root");
    return instance;
}

std::list<std::pair<std::string, YAML::Node>> ExtractMembers(const YAML::Node& node, const std::string& prefix) {
    std::list<std::pair<std::string, YAML::Node>> members;
    if (node.IsMap()) {
        for (const auto& [key, value] : node) {
            std::string new_key = prefix.empty() ? key.as<std::string>() : prefix + "." + key.as<std::string>();
            members.emplace_back(new_key, value);
            auto sub_members = ExtractMembers(value, new_key);
            members.insert(members.end(), sub_members.begin(), sub_members.end());
        }
    }
    return members;
}
}
